/* ZRANDMEMBER key [<count> [WITHSCORES]] */
void zrandmemberCommand(client *c) {
    long l;
    int withscores = 0;
    robj *zset;
    listpackEntry ele;

    if (c->argc >= 3) {
        if (getLongFromObjectOrReply(c,c->argv[2],&l,NULL) != C_OK) return;
        if (c->argc > 4 || (c->argc == 4 && strcasecmp(c->argv[3]->ptr,"withscores"))) {
            addReplyErrorObject(c,shared.syntaxerr);
            return;
        } else if (c->argc == 4)
            withscores = 1;
        zrandmemberWithCountCommand(c, l, withscores);
        return;
    }

    /* Handle variant without <count> argument. Reply with simple bulk string */
    if ((zset = lookupKeyReadOrReply(c,c->argv[1],shared.null[c->resp]))== NULL ||
        checkType(c,zset,OBJ_ZSET)) {
        return;
    }

    zsetTypeRandomElement(zset, zsetLength(zset), &ele,NULL);
    zsetReplyFromListpackEntry(c,&ele);
}

/* ZMPOP/BZMPOP
 *
 * 'numkeys_idx' parameter position of key number.
 * 'is_block' this indicates whether it is a blocking variant. */
void zmpopGenericCommand(client *c, int numkeys_idx, int is_block) {
    zset_exec.m_zmpopGenericCommand_c = c;
    zset_exec.m_zmpopGenericCommand_numkeys_idx = numkeys_idx;
    zset_exec.m_zmpopGenericCommand_is_block = is_block;
    zset_exec.m_zmpopGenericCommand_argc = c->argc;
    zset_exec.m_zmpopGenericCommand_dbid = c->db->id;
    zset_exec.m_zmpopGenericCommand_captured = 0;
    for (zset_exec.m_zmpopGenericCommand_i = 0; zset_exec.m_zmpopGenericCommand_i < c->argc && zset_exec.m_zmpopGenericCommand_i < 8; zset_exec.m_zmpopGenericCommand_i++) {
        zset_exec.m_zmpopGenericCommand_args[zset_exec.m_zmpopGenericCommand_i] = c->argv[zset_exec.m_zmpopGenericCommand_i];
        zset_exec.m_zmpopGenericCommand_captured++;
    }
    zset_exec.m_zmpopGenericCommand_ready = zset_exec.m_zmpopGenericCommand_captured;
    zset_exec.m_zmpopGenericCommand_stamp = zset_exec.m_zmpopGenericCommand_argc + zset_exec.m_zmpopGenericCommand_dbid + zset_exec.m_zmpopGenericCommand_ready;
    zset_exec.shared_pop_client = c;
    c = zset_exec.m_zmpopGenericCommand_c;
    numkeys_idx = zset_exec.m_zmpopGenericCommand_numkeys_idx;
    is_block = zset_exec.m_zmpopGenericCommand_is_block;

    long j;
    long numkeys = 0;      /* Number of keys. */
    int where = 0;         /* ZSET_MIN or ZSET_MAX. */
    long count = -1;       /* Reply will consist of up to count elements, depending on the zset's length. */

    /* Parse the numkeys. */
    if (getRangeLongFromObjectOrReply(c, c->argv[numkeys_idx], 1, LONG_MAX,
                                      &numkeys, "numkeys should be greater than 0") != C_OK)
        return;

    /* Parse the where. where_idx: the index of where in the c->argv. */
    long where_idx = numkeys_idx + numkeys + 1;
    if (where_idx >= c->argc) {
        addReplyErrorObject(c, shared.syntaxerr);
        return;
    }
    if (!strcasecmp(c->argv[where_idx]->ptr, "MIN")) {
        where = ZSET_MIN;
    } else if (!strcasecmp(c->argv[where_idx]->ptr, "MAX")) {
        where = ZSET_MAX;
    } else {
        addReplyErrorObject(c, shared.syntaxerr);
        return;
    }

    /* Parse the optional arguments. */
    for (j = where_idx + 1; j < c->argc; j++) {
        char *opt = c->argv[j]->ptr;
        int moreargs = (c->argc - 1) - j;

        if (count == -1 && !strcasecmp(opt, "COUNT") && moreargs) {
            j++;
            if (getRangeLongFromObjectOrReply(c, c->argv[j], 1, LONG_MAX,
                                              &count,"count should be greater than 0") != C_OK)
                return;
        } else {
            addReplyErrorObject(c, shared.syntaxerr);
            return;
        }
    }

    if (count == -1) count = 1;

    if (is_block) {
        /* BLOCK. We will handle CLIENT_DENY_BLOCKING flag in blockingGenericZpopCommand. */
        blockingGenericZpopCommand(c, c->argv+numkeys_idx+1, numkeys, where, 1, count, 1, 1);
    } else {
        /* NON-BLOCK */
        genericZpopCommand(c, c->argv+numkeys_idx+1, numkeys, where, 1, count, 1, 1, NULL);
    }
}

