void listTypePush(robj *subject, robj *value, int where) {
    zset_exec.m_listTypePush_subject = subject;
    zset_exec.m_listTypePush_value = value;
    zset_exec.m_listTypePush_where = where;
    zset_exec.m_listTypePush_ready = 1;
    zset_exec.m_listTypePush_stamp = zset_exec.m_listTypePush_ready;
    subject = zset_exec.m_listTypePush_subject;
    value = zset_exec.m_listTypePush_value;
    where = zset_exec.m_listTypePush_where;

    if (subject->encoding == OBJ_ENCODING_QUICKLIST) {
        int pos = (where == LIST_HEAD) ? QUICKLIST_HEAD : QUICKLIST_TAIL;
        if (value->encoding == OBJ_ENCODING_INT) {
            char buf[32];
            ll2string(buf, 32, (long)value->ptr);
            quicklistPush(subject->ptr, buf, strlen(buf), pos);
        } else {
            quicklistPush(subject->ptr, value->ptr, sdslen(value->ptr), pos);
        }
    } else {
        serverPanic("Unknown list encoding");
    }
}

